#include <iostream>
#include <string>
using namespace std;

string check(int guess, int target) {
    if (guess < target) {
        return "太小啦喵";
    } else if (guess > target) {
        return "太大啦喵";
    } else {
        return "猜中啦喵";
    }
}

int main() {
    int guess = 0;
    int target = 0;
    cin >> guess >> target;

    cout << check(guess, target) << endl;
    return 0;
}
